test('room chat self-send reveals its message while remote updates retain reading anchors and typing focus',{timeout:60000},async()=>{
 const fs=require('node:fs'),repo=path.resolve(__dirname,'..'),out=process.env.PLAYROOM_CHAT_SCROLL_REPORT_DIR;
 const engine=process.env.PLAYROOM_CHAT_ENGINE||'chromium',browser=engine==='webkit'?await require('playwright-core').webkit.launch({headless:true,executablePath:process.env.PLAYROOM_WEBKIT_EXECUTABLE}):await chromium.launch({headless:true,executablePath:executablePath(),args:['--no-sandbox','--disable-background-networking']}),server=await serveBrowserFixture(repo),report=[];
 try{for(const kind of (process.env.PLAYROOM_CHAT_KIND?[process.env.PLAYROOM_CHAT_KIND]:['room','direct']))for(const [width,height,touch]of [[390,664,true],[844,320,true],[1366,768,false]]){
  const context=await browser.newContext({viewport:{width,height},hasTouch:touch,isMobile:touch,serviceWorkers:'block',reducedMotion:'reduce'}),page=await context.newPage(),errors=[];
  const network=await require('./account-sync-fixture.cjs').installFetch(context,route=>route.fulfill({json:{}}));page.on('pageerror',e=>errors.push(e.message));page.setDefaultTimeout(7000);
  try{await context.addInitScript(()=>{localStorage.setItem('playroom.player-profile.v1',JSON.stringify({version:1,id:'chat-anchor',name:'Проверка'}));localStorage.setItem('playroom.settings.v1',JSON.stringify({sound:false,tutorialsEnabled:false}));});
   if(process.env.PLAYROOM_TEST_ARTIFACT)await page.route(server.url,route=>route.fulfill({contentType:'text/html',body:fs.readFileSync(process.env.PLAYROOM_TEST_ARTIFACT)}));
   await page.goto(server.url);await page.locator('[data-start=uno]').click();await page.locator('[data-game-mode=network]').click();await page.locator('.room-v021').waitFor();
   // Isolated source port: the real panel, rich composer, keyed renderer and
   // cache remain in use. This is not a real network delivery assertion.
   await page.evaluate(kind=>{const room=PlayroomAppBridge.room(),rows=Array.from({length:30},(_,i)=>({id:String(i+1),seq:String(i+1),body:'Сообщение '+(i+1),nickname:'Мика',mine:false,at:new Date().toISOString()}));
    window.chatAnchorKey='room:'+room.id+':'+room.ownerId+':room';window.chatAnchorRows=rows;
    window.chatAnchorContext={roomId:room.id,participantId:room.ownerId,game:{id:'uno',name:'UNO'},roomName:'Проверка',connected:true,call:async request=>{if(request.type==='room-chat-send')rows.push({id:String(rows.length+1),seq:String(rows.length+1),body:request.body,nickname:'Проверка',mine:true,at:new Date().toISOString()});return {messages:rows,through:String(rows.length),older:false};}};
    if(kind==='direct'){chatAnchorKey='dm:peer-anchor';PlayroomCommunityUI.init({account:{snapshot:()=>({kind:'account',id:'anchor-account'}),subscribe:()=>()=>{}},remote:{call:async(action,data)=>{if(action==='send-message')rows.push({id:String(rows.length+1),body:data.body,nickname:'Проверка',mine:true,at:new Date().toISOString()});return {messages:rows,through:String(rows.length),friends:[],groups:[],chats:[]};}}});PlayroomChatUI.show({userId:'peer-anchor',nickname:'Мика',accepted:true,online:true});}else PlayroomRoomChatUI.show({source:()=>chatAnchorContext});},kind);
   const panel=kind==='room'?page.locator('.game-chat-panel'):page.locator('#modal-root>[data-surface-state=active]'),list=panel.locator('[data-room-chat-messages],[data-chat-messages]'),editor=panel.locator('[data-chat-editor]');await list.locator('.chat-message').last().waitFor();if(kind==='room')await page.waitForFunction(()=>PlayroomGameChatPanel.interactive);
   await list.evaluate(node=>node.scrollTop=140);await editor.fill('Сохранить черновик');
   await page.evaluate(()=>{window.chatAnchorEditor=document.querySelector('[data-chat-editor]');window.chatAnchorFirst=document.querySelector('.chat-message');window.chatAnchorList=document.querySelector('[data-room-chat-messages],[data-chat-messages]');});
   const before=await list.evaluate(node=>node.scrollTop);
   await page.evaluate(()=>{const row={id:'31',seq:'31',body:'Входящее во время чтения',nickname:'Мика',mine:false,at:new Date().toISOString()};chatAnchorRows.push(row);PlayroomChatState.refreshInvitations(chatAnchorKey,[row]);});
   assert(Math.abs(await list.evaluate(node=>node.scrollTop)-before)<2,'remote append retains older reading offset');assert.equal(await editor.innerText(),'Сохранить черновик');assert(await editor.evaluate(node=>node===chatAnchorEditor&&document.activeElement===node),'remote append keeps editor DOM and focus');assert(await list.locator('.chat-message').first().evaluate(node=>node===chatAnchorFirst),'remote append retains existing message node');
   await editor.fill('Свое новое сообщение');await editor.press('Enter');await list.locator('.mine').filter({hasText:'Свое новое сообщение'}).waitFor();
   await page.waitForFunction(()=>{const n=document.querySelector('[data-room-chat-messages],[data-chat-messages]');return n.scrollHeight-n.clientHeight-n.scrollTop<2;});
   assert.equal(await editor.innerText(),'');assert(await editor.evaluate(node=>node===chatAnchorEditor&&document.activeElement===node),'self-send keeps typing focus');
   await editor.fill('Следующий черновик');await page.evaluate(()=>{const row={id:'33',seq:'33',body:'Входящее внизу',nickname:'Мика',mine:false,at:new Date().toISOString()};chatAnchorRows.push(row);PlayroomChatState.refreshInvitations(chatAnchorKey,[row]);});
   assert(await list.evaluate(node=>node.scrollHeight-node.clientHeight-node.scrollTop<2),'remote append follows a reader already pinned at bottom');assert.equal(await editor.innerText(),'Следующий черновик');assert(await editor.evaluate(node=>document.activeElement===node));
   await list.evaluate(node=>node.scrollTop=200);const reading=await list.evaluate(node=>PlayroomChatState.anchor(node));await panel.locator('[data-command=close-modal]').click();await page.waitForFunction(kind=>kind==='room'?!document.querySelector('.game-chat-panel'):PlayroomChatUI.currentUserId()===null,kind);await page.evaluate(kind=>kind==='room'?PlayroomRoomChatUI.show({source:()=>chatAnchorContext}):PlayroomChatUI.show({userId:'peer-anchor',nickname:'Мика',accepted:true,online:true}),kind);await list.waitFor();await page.evaluate(()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve))));const restored=await list.evaluate(node=>PlayroomChatState.anchor(node));assert.equal(restored.entity,reading.entity,'reopen retains deliberately read message: '+JSON.stringify({reading,restored}));assert(Math.abs(restored.offset-reading.offset)<3,'reopen retains message anchor offset: '+JSON.stringify({reading,restored}));assert.equal(await panel.locator('[data-chat-editor]').innerText(),'Следующий черновик');
   assert.deepEqual(errors,[]);assert.equal(network.nativeSupabaseRequests,0);report.push({kind,width,height,touch,selfSendBottom:true,remoteOlderAnchor:true,remotePinnedBottom:true,typingFocus:true,draft:true,keyedNode:true,errors});
   if(out){fs.mkdirSync(out,{recursive:true});await page.screenshot({path:path.join(out,engine+'-'+kind+'-chat-scroll-'+width+'.png')});}
  }finally{await context.close();}
 }}finally{if(out){fs.mkdirSync(out,{recursive:true});fs.writeFileSync(path.join(out,engine+'-chat-scroll.json'),JSON.stringify(report,null,2));}await browser.close();await server.close();}
});
